import React, { useState } from 'react';
import './PaymentStatusPage.css'; // Import CSS file for styling
import Dialog from '@material-ui/core/Dialog';
import Slide from '@material-ui/core/Slide';
import { useHistory, useParams } from 'react-router-dom';
import Logo from 'theme/Logo';
import CustomButton from 'components/CustomButton';
import CheckCircleIcon from '@material-ui/icons/CheckCircle';
import CancelIcon from '@material-ui/icons/Cancel';

const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const PaymentStatusPage = () => {
  const history = useHistory();
  const {
    //paymentOrderId,
    paymentStatus,
    amount,
  } = useParams();
  const [open, setOpen] = useState(true);

  const getSuccessContent = () => {
    return (
      <>
        <h3 className="heading-payment">Success</h3>
        <p className="pragraph-payment">
          We have received your payment for fee
          <br />
          Received amount: <b>₹{amount}.00</b>
        </p>
      </>
    );
  };

  const getFailureContent = () => {
    return (
      <>
        <h3 className="heading-failure-payment">Failed</h3>
        <p className="pragraph-payment">
          Oops! Payment could not be processed.
          <br />
          Please check and try again.
        </p>
      </>
    );
  };

  return (
    <Dialog fullScreen open={open} onClose={undefined} TransitionComponent={Transition}>
      <div className="main-container-payment">
        <div className="card-payment">
          <div style={{ textAlign: 'center' }}>
            <Logo />
          </div>
          <div className="container-payment" style={{ marginTop: 40, marginBottom: 30 }}>
            {paymentStatus === 'success' ? (
              <CheckCircleIcon className="icon-success-payment" />
            ) : (
              <CancelIcon className="icon-failure-payment" />
            )}
          </div>
          {paymentStatus === 'success' ? getSuccessContent() : getFailureContent()}
          <br />
          <CustomButton
            color="default"
            className="mt-5"
            name="Go to Students"
            onClick={() => {
              setOpen(false);
              history.push('/admin/school-students?school-students');
            }}
          />
        </div>
      </div>
    </Dialog>
  );
};

export default PaymentStatusPage;
